<script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import PageHeader from'../components/PageHeader.vue';import{queryEntity}from'../api/admin.js';const route=useRoute(),item=ref();onMounted(async()=>item.value=(await queryEntity('orders')).data.items.find(x=>x.id===route.params.id))</script><template><div class="admin-page" v-if="item"><PageHeader title="订单详情" :description="item.id"><el-button @click="$router.back()">返回</el-button><el-button type="primary">更新状态</el-button></PageHeader><div class="split"><section class="work-surface detail"><h2 class="section-title">订单信息</h2><dl class="detail-list"><dt>项目</dt><dd>{{item.project}}</dd><dt>客户</dt><dd>{{item.customer}}</dd><dt>设计师</dt><dd>{{item.designer}}</dd><dt>预算金额</dt><dd>¥ {{item.amount}}</dd><dt>交付日期</dt><dd>{{item.delivery}}</dd><dt>当前阶段</dt><dd><span class="status progress">{{item.stage}}</span></dd></dl><h2 class="section-title timeline-title">流程记录</h2><el-timeline><el-timeline-item timestamp="2026-08-20" type="primary">客户需求确认</el-timeline-item><el-timeline-item timestamp="2026-08-28" type="primary">设计方案提交</el-timeline-item><el-timeline-item timestamp="等待更新" hollow>生产与安装</el-timeline-item></el-timeline></section><aside class="work-surface detail"><h2 class="section-title">关联操作</h2><el-button style="width:100%">查看设计方案</el-button><el-button style="width:100%;margin:10px 0 0">查看生产任务</el-button></aside></div></div></template><style scoped>.detail{padding:24px 28px}.timeline-title{margin-top:32px;padding-top:24px;border-top:1px solid var(--border)}</style>
